import SwiftUI

struct CardStyle: ViewModifier {
    func body(content: Content) -> some View {
        content
            .padding(16)
            .background(Color.gray.opacity(0.2))
    }
}

extension View {
    func cardStyle() -> some View {
        modifier(CardStyle())
    }
}

struct TestView: View {
    var body: some View {
        Text("Card")
            .cardStyle()
    }
}

let test = TestView()
print("Card rendered: \(type(of: test))")

